#include <iostream>
#include <stack>
#include <deque>

int main() {
    // Create a std::deque with some elements
    std::deque<int> deq = {1, 2, 3, 4};  // FIFO container with elements

    // Construct a std::stack from the deque, copying elements
    std::stack<int> stk(deq);  // This copies elements from deq into stk

    // Demonstrate usage: pop elements from the stack (LIFO order)
    while (!stk.empty()) {
        std::cout << stk.top() << " ";  // Access top element
        stk.pop();  // Remove top element
    }
    // Output: 4 3 2 1 (elements in reverse order due to LIFO)
    std::cout << std::endl;

    return 0;
}
